import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

interface Todo {
  id: number;
  text: string;
  done: boolean;
}

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly newTask = signal('');
  readonly todos = signal<Todo[]>([]);
  readonly hasTodos = computed(() => this.todos().length > 0);
  private nextId = 1;

  addTask(): void {
    const text = this.newTask().trim();
    if (!text) {
      return;
    }

    this.todos.update((todos) => [...todos, { id: this.nextId++, text, done: false }]);
    this.newTask.set('');
  }

  toggleTask(id: number): void {
    // Replace the changed todo instead of editing it, so everything derived from todos() sees the change.
    this.todos.update((todos) =>
      todos.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo))
    );
  }

  removeTask(id: number): void {
    this.todos.update((todos) => todos.filter((todo) => todo.id !== id));
  }

  clearCompleted(): void {
    this.todos.update((todos) => todos.filter((todo) => !todo.done));
  }
}
